        { name = "BEDROCK_PROMPT_VERSION", value = "event-v1" },
        {
          name  = "CHALLENGER_MANIFEST_URI"
          value = "s3://${aws_s3_bucket.archive.id}/models/${var.challenger_run_id}/manifest.json"
